      out += "├─ Geometry info:\n"
      if "geometry_type" in self.ctx:
        out += f"│  ├─ Type: {self.ctx['geometry_type']}\n"
      if "geqdsk_sign_convention" in self.ctx:
        out += f"│  ├─ GEQDSK sign convention: {self.ctx['geqdsk_sign_convention']:d}\n"
    if any(k in self.ctx for k in ("mass", "charge", "gas_gamma", "vdim")):
      out += "├─ Species properties:\n"
      if "mass" in self.ctx:
        out += f"│  ├─ Mass: {self.ctx['mass']:e}\n"
      if "charge" in self.ctx:
        out += f"│  ├─ Charge: {self.ctx['charge']:e}\n"
      if "gas_gamma" in self.ctx:
        out += f"│  ├─ Adiabatic index: {self.ctx['gas_gamma']:e}\n"
      if "vdim" in self.ctx:
        out += f"│  ├─ Velocity dimensions: {self.ctx['vdim']:d}\n"
    for key, val in self.ctx.items():
      if key not in self._INFO_HANDLED_CTX_KEYS:
        out += f"├─ {key}: {val}\n"
    if provenance := self.ctx.get("_load_metadata"):
      if all:
        out += "├─ Metadata sources (at load; summary above is current state):\n"
      for key, title in (
          ("file_header", "File header (stored grid and array layout)"),
          ("file_metadata", "File metadata (verbatim keys)"),
          ("context", "Explicit initial context"),
          ("overrides", "Explicit load overrides"),
          ("defaults", "Inferred/defaulted"),
          ("filename", "Inferred from filename"),
      ):
        if not all and key != "defaults":
          continue
        entries = provenance.get(key, {})
        if not entries and key != "file_metadata":
          continue
        if key == "file_metadata" and key not in provenance:
          continue
        if not all:
          title += " at load (summary above is current state)"
        prefix = "│  " if all else ""
        out += f"{prefix}├─ {title}:"
        if not isinstance(entries, dict):
          out += f" {entries!r}\n"
        elif not entries:
          out += " <none>\n"
        else:
          out += "\n"
          for name, value in entries.items():
            if key == "defaults":
              value, reason = value
              out += f"{prefix}│  ├─ {name}: {value!r} ({reason})\n"
            else:
              out += f"{prefix}│  ├─ {name}: {value!r}\n"
    out += "└─ File: " + (self._file_name or "<no file>") + "\n"
    print(out)
    return out

